   348	bool SoftimagePICHandler::canRead(QIODevice *device)
   349	{
   350	    char data[4];
   351	    if (device->peek(data, 4) != 4) {
   352	        return false;
   353	    }
   354	    return qFromBigEndian<qint32>(reinterpret_cast<uchar*>(data)) == PIC_MAGIC_NUMBER;
   355	}
   356	
   357	bool SoftimagePICHandler::readHeader()
   358	{
   359	    if (m_state == Ready) {
   360	        m_state = Error;
   361	        m_dataStream.setDevice(device());
   362	        m_dataStream >> m_header;
   363	        if (m_header.isValid() && m_dataStream.status() == QDataStream::Ok) {
   364	            m_state = ReadHeader;
   365	        }
   366	    }
   367	    return m_state != Error;
   368	}
   369	
   370	bool SoftimagePICHandler::readChannels()
   371	{
   372	    readHeader();
   373	    if (m_state == ReadHeader) {
   374	        m_state = Error;
   375	        m_dataStream >> m_channels;
   376	        if (m_dataStream.status() == QDataStream::Ok) {
   377	            m_state = ReadChannels;
   378	        }
   379	    }
   380	    return m_state != Error;
   381	}
